from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/")
async def read_header(my_header: str = Header()):
    return {"my_header": my_header}

client = TestClient(app)

def test_underscore_header_accepted_by_default():
    # By default convert_underscores=True. 
    # It should accept 'my-header'
    response = client.get("/", headers={"my-header": "foo"})
    assert response.status_code == 200
    assert response.json() == {"my_header": "foo"}

    # The issue says: "Do not accept underscore headers when using convert_underscores=True"
    # So this should probably fail or not return the value if we want to enforce this.
    # Currently, if we send 'my_header', does it work?
    response = client.get("/", headers={"my_header": "bar"})
    print(f"Response with my_header: {response.json()}")
    # If it returns {"my_header": "bar"}, then it IS accepting underscore headers.
    # The goal is to NOT accept it.
    # assert response.json() != {"my_header": "bar"}

def test_underscore_header_accepted_when_disabled():
    # When convert_underscores=False, it should accept 'my_header'
    @app.get("/disabled")
    async def read_header_disabled(my_header: str = Header(convert_underscores=False)):
        return {"my_header": my_header}

    response = client.get("/disabled", headers={"my_header": "bar"})
    assert response.status_code == 200
    assert response.json() == {"my_header": "bar"}

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])

